pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public {
        c = new FlashGovernanceArbiter(address(this));
    }
    function testRegression_property() public {
        address addr = address(0x123);
        address[] memory governables = new address[](1);
        governables[0] = addr;
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);
        try c.assertGovernanceApproved(addr, address(0), false) {} catch {}
        assertTrue(c.governed(addr));
    }
}
